    public partial class ASTVisualizer : IASTVisitor
    { 
        private IASTTraverser _traverser;
        private StringBuilder _sb = new();
        private string _input = string.Empty;
        protected override void OnInitialized()
        {
            _traverser = SQLBuilderHelper.ASTWalkerBuiler(this);
            LoadExpr(1);
        }
        private void CreateAST()
        {
            _sb.Clear();

            try
            {
                _traverser.Walk(SQLBuilderHelper.BuildExpression(_input));
            }
            catch (Exception)
            {
                try
                {
                    foreach(var select in SQLBuilderHelper.BuildSelect(_input))
                    {
                        _traverser.Walk(select);
                    }
                }
                catch (Exception)
                {
                    try
                    {
                        foreach (var order in SQLBuilderHelper.BuildOrderBy(_input))
                        {
                            _traverser.Walk(order);
                        }
                    }
                    catch (Exception ex)
                    {
                        createError(ex.Message);
                    }
                }
            }

            StateHasChanged();
        }
        private void LoadExpr(int num)
        {
            switch (num)
            {
                case 2:
                    _input = "case [r].\"name\" like '%corsair%' when 1 then 'Corsair RAM' else 'Other RAM' end";
                    _sb.Clear();
                    _sb.Append("Create AST to see results!");
                    break;
                case 1:
                default:
                    _input = "r.name = 'corsair'";
                    _sb.Clear();
                    _sb.Append("Create AST to see results!");
                    break;
            }

            StateHasChanged();
        }
        //helper
        private void Div(string cssClass, Action content, string style = null)
        {
            _sb.Append($"<div class=\"{cssClass}\" style=\"{style??string.Empty}\">");

            content();

            _sb.Append("</div>");
        }
        private void createError(string message)
        {
            _sb.Append($"<pre class=\"bg-danger-subtle p-3\">{message}</pre>");
        }

